use std::{fs,path::{Path,PathBuf}};use sha2::{Digest,Sha256};use serde_json::Value;
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),out)}else if e.file_type().unwrap().is_file(){out.push(e.path());}}}
fn main(){let root=Path::new("/tmp/zopro-pairing-x-chain");let dest=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-pairing-x-chain/artifacts");let index=dest.join("artifact-index.json");let mut v:Value=serde_json::from_slice(&fs::read(&index).unwrap()).unwrap();let mut files=Vec::new();for d in ["initial-snapshot-mismatch","pre-capture-config"]{walk(&root.join(d),&mut files);}for f in ["archive-extra.rs","closeout.json"]{files.push(root.join(f));}for p in files{let rel=p.strip_prefix(root).unwrap();let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();v["sha256"][rel.display().to_string()]=Value::String(format!("{:x}",Sha256::digest(fs::read(target).unwrap())));}for(p,h)in v["sha256"].as_object().unwrap(){assert_eq!(format!("{:x}",Sha256::digest(fs::read(dest.join(p)).unwrap())),h.as_str().unwrap());}fs::write(index,serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("{}checkedarchivehashes",v["sha256"].as_object().unwrap().len());}
